/**
 * Embedded OG-card fonts (base64 TrueType).
 *
 * Two MB Type faces, subset to a Latin glyph set, decompressed from the
 * project WOFF2 masters and inlined here so the OG generator has zero runtime
 * font I/O and bundles cleanly into the Vercel serverless function.
 *
 *   Concourse 8 (black)  -> og card headline
 *   Triplicate OT A      -> og card eyebrow / date / domain
 *
 * DO NOT hand-edit the base64 blobs.
 */

function decode(b64: string): Buffer {
  return Buffer.from(b64, "base64");
}

const CONCOURSE_8_BLACK_B64 =
  "";

const TRIPLICATE_REGULAR_B64 =
  "";

export const CONCOURSE_BLACK: Buffer = decode(CONCOURSE_8_BLACK_B64);
export const TRIPLICATE_REGULAR: Buffer = decode(TRIPLICATE_REGULAR_B64);
